package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's customerCode, formatted {@code <LAST3>-<NNNN>} where LAST3 is the upper-cased
 * first three letters of the last name and NNNN is a global 4-digit zero-padded sequence equal to
 * one more than the current number of owners (e.g. {@code SMI-0007}). Runs before {@link SaveOwner},
 * so the count excludes the owner currently being created. Mutates the built {@link Owner} in place.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String lastName = owner.getLastName();
        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
        int sequence = ownerRepository.findAll().size() + 1;
        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
    }
}

