1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When the create request sets {@code sharesHousehold} true and the new owner joins a household
10	 * already occupied by an existing owner (same last name and address, see {@link HouseholdNormalizer}),
11	 * stamps the new owner and every existing member of that household with the same stable
12	 * {@link HouseholdNormalizer#id(String, String) household id}. Without {@code sharesHousehold} the
13	 * request never reaches here as a joiner — {@link EnsureUniqueHousehold} rejects the collision first —
14	 * so a lone owner keeps a null household id. Runs after {@link BuildOwner} and mutates the built
15	 * {@link Owner} in place; existing members are re-saved so a later read returns the shared id too.
16	 */
17	public class AssignHousehold {
18	
19	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
20	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String key = HouseholdNormalizer.key(owner.getLastName(), owner.getAddress());
24	        boolean joinsHousehold = false;
25	        String householdId = HouseholdNormalizer.id(owner.getLastName(), owner.getAddress());
26	        for (Owner member : ownerRepository.findAll()) {
27	            if (!key.equals(HouseholdNormalizer.key(member.getLastName(), member.getAddress()))) {
28	                continue;
29	            }
30	            joinsHousehold = true;
31	            if (!householdId.equals(member.getHouseholdId())) {
32	                member.setHouseholdId(householdId);
33	                ownerRepository.save(member);
34	            }
35	        }
36	        if (joinsHousehold) {
37	            owner.setHouseholdId(householdId);
38	        }
39	    }
40	}
