17	            if (owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
18	                    && owner.getLastName().equalsIgnoreCase(existing.getLastName())) {
19	                namesakes++;
20	            }
21	        }
22	        owner.setNamesakeCount(namesakes);
23	    }
24	}
